import csv
import io
import re

def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str) or not raw_csv:
        return {"columns": [], "rows": []}

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = []
    try:
        for record in reader:
            if record and not (len(record) == 1 and record[0] == ""):
                records.append(record)
    except csv.Error:
        pass

    if not records:
        return {"columns": [], "rows": []}

    width = 9

    def header_like(record):
        if len(record) < width:
            return False
        text = " ".join(record[:width]).lower()
        terms = (
            "date", "time", "quantity", "qty", "product", "price",
            "description", "url", "comment", "type", "id"
        )
        return sum(1 for term in terms if term in text) >= 2

    header_index = None
    for index, record in enumerate(records):
        if header_like(record):
            header_index = index
            break

    if header_index is None:
        for index, record in enumerate(records):
            if len(record) >= width:
                header_index = index
                break

    if header_index is None:
        header_index = 0

    def normalize_header(record):
        values = list(record)
        if len(values) < width:
            values.extend([""] * (width - len(values)))
        elif len(values) > width:
            values = values[:width - 1] + [",".join(values[width - 1:])]
        if values:
            values[0] = values[0].lstrip("\ufeff")
        return values

    def normalize_row(record):
        values = list(record)

        if len(values) == width:
            return values

        if len(values) < width:
            return values + [""] * (width - len(values))

        url_index = None
        for index in range(5, len(values)):
            if re.search(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", values[index].strip()):
                url_index = index
                break

        if url_index is not None and url_index >= 6:
            fixed = values[:5]
            middle = values[5:url_index]
            url = values[url_index]
            comments = ",".join(values[url_index + 1:])

            if not middle:
                product_type = ""
                description = ""
            elif len(middle) == 1:
                product_type = middle[0]
                description = ""
            elif len(middle) == 2:
                product_type, description = middle
            else:
                split_at = 1
                for index in range(1, len(middle) - 1):
                    part = middle[index].strip()
                    if (
                        len(part) >= 35
                        or re.search(r"[.!?]$", part)
                        or re.match(
                            r"(?i)^(our|made|with|these|this|great|designed|"
                            r"for|an|a|the|all|inspired|here|were|we)\b",
                            part,
                        )
                    ):
                        split_at = index
                        break
                product_type = ",".join(middle[:split_at])
                description = ",".join(middle[split_at:])

            return fixed + [product_type, description, url, comments]

        return values[:width - 1] + [",".join(values[width - 1:])]

    columns = normalize_header(records[header_index])
    rows = [
        normalize_row(record)
        for record in records[header_index + 1:]
        if record
    ]

    return {"columns": columns, "rows": rows}
